fn_apply_moderation_transparency_daily_r.definition:
CREATE OR REPLACE FUNCTION public.fn_apply_moderation_transparency_daily_rollup(p_occurred_at timestamp with time zone, p_community_id uuid, p_metric moderation_transparency_metrics, p_category moderation_transparency_categories, p_delta integer)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE p_day date := (p_occurred_at AT TIME ZONE 'UTC')::date;
BEGIN
  IF p_delta = 0 THEN RETURN; END IF;
  -- Source deletes can hold many FK/cascade row locks. Serialize them against
  -- positive ingestion before either path acquires cohort locks: otherwise two
  -- multi-cohort deletes can interleave their row and advisory lock order.
  IF p_delta < 0 THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('moderation-transparency-rollup-write', 0));
  ELSE
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('moderation-transparency-rollup-write', 0));
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    'moderation-transparency-rollup:' || p_day::text || ':'
      || COALESCE(p_community_id::text, 'global') || ':' || p_metric || ':' || p_category,
    0
  ));
  IF EXISTS (
    SELECT 1 FROM moderation_transparency_released_daily_rollups
    WHERE day = p_day AND community_id IS NOT DISTINCT FROM p_community_id
      AND metric = p_metric AND category = p_category
  ) THEN RETURN; END IF;
  IF p_delta < 0 THEN
    PERFORM fn_release_moderation_transparency_daily_rollup(
      p_day, p_community_id, p_metric, p_category,
      date_trunc('day', clock_timestamp() - interval '48 hours') - interval '1 millisecond'
    );
  END IF;
  IF p_delta > 0 THEN
    INSERT INTO moderation_transparency_daily_rollups(day, community_id, metric, category, count, latest_occurred_at)
    VALUES (p_day, p_community_id, p_metric, p_category, p_delta, p_occurred_at)
    ON CONFLICT ON CONSTRAINT moderation_transparency_daily_rollups_key DO UPDATE
      SET count = moderation_transparency_daily_rollups.count + EXCLUDED.count,
          latest_occurred_at = GREATEST(moderation_transparency_daily_rollups.latest_occurred_at, EXCLUDED.latest_occurred_at);
  ELSE
    DELETE FROM moderation_transparency_daily_rollups
      WHERE day = p_day AND community_id IS NOT DISTINCT FROM p_community_id
        AND metric = p_metric AND category = p_category AND count <= -p_delta;
    UPDATE moderation_transparency_daily_rollups
      SET count = count + p_delta
      WHERE day = p_day AND community_id IS NOT DISTINCT FROM p_community_id
        AND metric = p_metric AND category = p_category;
  END IF;
END $function$

fn_create_media_delivery_generation_chan.definition:
CREATE OR REPLACE FUNCTION public.fn_create_media_delivery_generation_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.generation IS DISTINCT FROM OLD.generation THEN
    INSERT INTO media_delivery_registry_changes(delivery_key, generation, change_type)
      VALUES (NEW.delivery_key, NEW.generation, 'pending');
  END IF;
  RETURN NEW;
END;
$function$

fn_create_metrics().definition:
CREATE OR REPLACE FUNCTION public.fn_create_metrics()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  EXECUTE format('INSERT INTO %I.%I (%I) VALUES ($1) ON CONFLICT (%I) DO NOTHING',
    TG_TABLE_SCHEMA, TG_ARGV[0], TG_ARGV[1], TG_ARGV[1]) USING NEW.id;
  RETURN NEW;
END;
$function$

fn_create_user_individual_household().definition:
CREATE OR REPLACE FUNCTION public.fn_create_user_individual_household()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  new_individual_id UUID;
  new_household_id UUID;
BEGIN
  -- Create individual
  INSERT INTO individuals DEFAULT VALUES
  RETURNING id INTO new_individual_id;

  -- Link individual to user
  UPDATE users
  SET individual_id = new_individual_id
  WHERE id = NEW.id;

  -- Create household owned by user
  INSERT INTO households (owner_user_id)
  VALUES (NEW.id)
  RETURNING id INTO new_household_id;

  -- Create membership linking individual to household
  INSERT INTO household_members (household_id, individual_id)
  VALUES (new_household_id, new_individual_id);

  RETURN NEW;
END;
$function$

