fn_ensure_retained_identity(family retai.definition:
CREATE OR REPLACE FUNCTION public.fn_ensure_retained_identity(family retained_identity_families, identity_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  owner_table TEXT := 'retained_' || family::text || '_identities';
  pinned_id UUID;
BEGIN
  -- Cleanup can remove an orphan between the conflict and key-share reads.
  -- Retry until this transaction pins the retained owner.
  LOOP
    EXECUTE format('INSERT INTO %I (id) VALUES ($1) ON CONFLICT (id) DO NOTHING', owner_table)
      USING identity_id;
    EXECUTE format('SELECT id FROM %I WHERE id = $1 FOR KEY SHARE', owner_table)
      INTO pinned_id USING identity_id;
    EXIT WHEN pinned_id IS NOT NULL;
  END LOOP;
END;
$function$

fn_guard_copyright_eu_dispute_settlement.definition:
CREATE OR REPLACE FUNCTION public.fn_guard_copyright_eu_dispute_settlement_outcome()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  referral_time timestamptz;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'EU dispute settlement outcomes are retained' USING ERRCODE = 'check_violation';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT referred_at INTO referral_time FROM copyright_eu_dispute_settlement_referrals
    WHERE id = NEW.copyright_eu_dispute_settlement_referral_id;
    IF referral_time IS NULL OR NEW.decided_at < referral_time THEN
      RAISE EXCEPTION 'EU dispute settlement outcome predates referral' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END IF;
  -- Account erasure may clear an audit actor without rewriting the outcome.
  IF OLD.recorded_by_id IS NOT NULL AND NEW.recorded_by_id IS NULL
    AND (to_jsonb(NEW) - 'recorded_by_id') IS NOT DISTINCT FROM (to_jsonb(OLD) - 'recorded_by_id') THEN
    RETURN NEW;
  END IF;
  IF OLD.implemented_at IS NOT NULL OR NEW.implemented_at IS NULL
    OR NEW.implemented_at < OLD.decided_at
    OR (to_jsonb(NEW) - 'implemented_at') IS DISTINCT FROM (to_jsonb(OLD) - 'implemented_at') THEN
    RAISE EXCEPTION 'EU dispute settlement outcome history cannot be rewritten'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_lock_active_user_for_mutation(target_.definition:
CREATE OR REPLACE FUNCTION public.fn_lock_active_user_for_mutation(target_user_id uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(target_user_id::TEXT, 0));
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = target_user_id) THEN
    RAISE EXCEPTION 'user % does not exist', target_user_id
      USING ERRCODE = 'no_data_found';
  ELSIF NOT EXISTS (SELECT 1 FROM users WHERE id = target_user_id AND deleted_at IS NULL) THEN
    RAISE EXCEPTION 'user % cannot own new data after deletion', target_user_id
      USING ERRCODE = 'check_violation';
  END IF;
END;
$function$

fn_lock_agent_moderation_transparency_co.definition:
CREATE OR REPLACE FUNCTION public.fn_lock_agent_moderation_transparency_community_prompt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_prompt_id uuid := COALESCE(NEW.id, OLD.id); v_agent_id uuid;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    -- Existing source rows have already captured their transparency scope.
    -- Do not take a projection advisory lock while a CAP UPDATE/DELETE owns
    -- its child row: a parent hard-delete owns the parent row and cascades to
    -- that child, so either lock order would form a parent/child/advisory
    -- cycle. These lifecycle changes deliberately leave prior stamps alone.
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;
  -- The child FK lock is acquired after BEFORE INSERT triggers. Acquire the
  -- parent first so parent deletion cannot deadlock on the advisory locks.
  PERFORM 1 FROM agent_prompts WHERE id = v_prompt_id FOR KEY SHARE;
  SELECT agent_id INTO v_agent_id FROM agent_prompts WHERE id = v_prompt_id;
  PERFORM fn_lock_moderation_transparency_projection('agent', v_agent_id);
  PERFORM fn_lock_moderation_transparency_projection('prompt', v_prompt_id);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

fn_lock_agent_moderation_transparency_pr.definition:
CREATE OR REPLACE FUNCTION public.fn_lock_agent_moderation_transparency_prompt()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_agent_id uuid;
BEGIN
  SELECT agent_id INTO v_agent_id FROM agent_prompts WHERE id = OLD.id;
  PERFORM fn_lock_moderation_transparency_projection('agent', v_agent_id);
  PERFORM fn_lock_moderation_transparency_projection('prompt', OLD.id);
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

fn_lock_bluesky_follow_receipt_active_us.definition:
CREATE OR REPLACE FUNCTION public.fn_lock_bluesky_follow_receipt_active_users()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.follower_user_id <= NEW.followee_user_id THEN
    PERFORM fn_lock_active_user_for_mutation(NEW.follower_user_id);
    IF NEW.followee_user_id <> NEW.follower_user_id THEN
      PERFORM fn_lock_active_user_for_mutation(NEW.followee_user_id);
    END IF;
  ELSE
    PERFORM fn_lock_active_user_for_mutation(NEW.followee_user_id);
    PERFORM fn_lock_active_user_for_mutation(NEW.follower_user_id);
  END IF;
  RETURN NEW;
END;
$function$

fn_project_activitypub_inbox_delivery_re.definition:
CREATE OR REPLACE FUNCTION public.fn_project_activitypub_inbox_delivery_retention()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  unverified_deadline TIMESTAMPTZ := NEW.received_at + INTERVAL '1 hour';
  failure_deadline TIMESTAMPTZ;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.failed_at IS NOT NULL THEN
      NEW.first_failed_at := NEW.failed_at;
    ELSE
      NEW.first_failed_at := NULL;
    END IF;
  ELSIF OLD.first_failed_at IS NOT NULL THEN
    NEW.first_failed_at := OLD.first_failed_at;
  ELSIF NEW.failed_at IS NOT NULL THEN
    NEW.first_failed_at := NEW.failed_at;
  ELSE
    NEW.first_failed_at := NULL;
  END IF;

  IF NEW.first_failed_at IS NOT NULL THEN
    failure_deadline := NEW.first_failed_at + INTERVAL '7 days';
  END IF;

  IF NEW.verified_at IS NULL THEN
    NEW.retention_expires_at := LEAST(
      COALESCE(NEW.retention_expires_at, unverified_deadline),
      unverified_deadline,
      COALESCE(failure_deadline, unverified_deadline)
    );
  ELSIF NEW.first_failed_at IS NULL THEN
    NEW.retention_expires_at := NULL;
  ELSE
    NEW.retention_expires_at := LEAST(
      COALESCE(OLD.retention_expires_at, NEW.retention_expires_at, failure_deadline),
      COALESCE(NEW.retention_expires_at, failure_deadline),
      failure_deadline
    );
  END IF;

  RETURN NEW;
END;
$function$

fn_project_activitypub_inbox_delivery_st.definition:
CREATE OR REPLACE FUNCTION public.fn_project_activitypub_inbox_delivery_storage_after_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  retained_rows_delta BIGINT;
  retained_bytes_delta BIGINT;
  unverified_rows_delta BIGINT;
  unverified_bytes_delta BIGINT;
BEGIN
  SELECT COUNT(*),
         COALESCE(SUM(OCTET_LENGTH(raw_body)), 0),
         COUNT(*) FILTER (WHERE verified_at IS NULL),
         COALESCE(SUM(OCTET_LENGTH(raw_body)) FILTER (WHERE verified_at IS NULL), 0)
  INTO retained_rows_delta, retained_bytes_delta, unverified_rows_delta, unverified_bytes_delta
  FROM deleted_deliveries;

  UPDATE activitypub_inbox_delivery_storage_counters
  SET retained_rows = retained_rows - retained_rows_delta,
      retained_raw_body_bytes = retained_raw_body_bytes - retained_bytes_delta,
      unverified_rows = unverified_rows - unverified_rows_delta,
      unverified_raw_body_bytes = unverified_raw_body_bytes - unverified_bytes_delta
  WHERE singleton;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'ActivityPub inbox storage counter singleton is missing';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.fn_project_activitypub_inbox_delivery_storage_after_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  retained_rows_delta BIGINT;
  retained_bytes_delta BIGINT;
  unverified_rows_delta BIGINT;
  unverified_bytes_delta BIGINT;
  counters activitypub_inbox_delivery_storage_counters%ROWTYPE;
BEGIN
  SELECT COUNT(*),
         COALESCE(SUM(OCTET_LENGTH(raw_body)), 0),
         COUNT(*) FILTER (WHERE verified_at IS NULL),
         COALESCE(SUM(OCTET_LENGTH(raw_body)) FILTER (WHERE verified_at IS NULL), 0)
  INTO retained_rows_delta, retained_bytes_delta, unverified_rows_delta, unverified_bytes_delta
  FROM inserted_deliveries;

  UPDATE activitypub_inbox_delivery_storage_counters
  SET retained_rows = retained_rows + retained_rows_delta,
      retained_raw_body_bytes = retained_raw_body_bytes + retained_bytes_delta,
      unverified_rows = unverified_rows + unverified_rows_delta,
      unverified_raw_body_bytes = unverified_raw_body_bytes + unverified_bytes_delta
  WHERE singleton
    AND (unverified_rows_delta <= 0 OR unverified_rows + unverified_rows_delta <= 10000)
    AND (
      unverified_bytes_delta <= 0
      OR unverified_raw_body_bytes + unverified_bytes_delta <= 268435456
    )
  RETURNING * INTO counters;

  IF FOUND THEN
    RETURN NULL;
  END IF;

  SELECT * INTO counters
  FROM activitypub_inbox_delivery_storage_counters
  WHERE singleton;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING
      ERRCODE = '55000',
      MESSAGE = 'ActivityPub inbox storage counter singleton is missing';
  END IF;
  RAISE EXCEPTION USING
    ERRCODE = '23514',
    CONSTRAINT = 'activitypub_inbox_deliveries_unverified_capacity',
    MESSAGE = 'ActivityPub inbox unverified storage capacity exceeded',
    DETAIL = json_build_object(
      'unverifiedRows', counters.unverified_rows,
      'unverifiedRawBodyBytes', counters.unverified_raw_body_bytes,
      'attemptedRows', unverified_rows_delta,
      'attemptedRawBodyBytes', unverified_bytes_delta
    )::TEXT;
END;
$function$

fn_project_activitypub_post_likes().definition:
CREATE OR REPLACE FUNCTION public.fn_project_activitypub_post_likes()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_delta INT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_delta := 1;
  ELSIF OLD.deleted_at IS NOT DISTINCT FROM NEW.deleted_at THEN
    RETURN NEW;
  ELSIF OLD.deleted_at IS NULL THEN
    v_delta := -1;
  ELSE
    v_delta := 1;
  END IF;

  INSERT INTO post_activitypub_like_tallies (post_id, activitypub_likes_score, activitypub_likes_count)
  VALUES (NEW.post_id, GREATEST(v_delta, 0), GREATEST(v_delta, 0))
  ON CONFLICT (post_id) DO UPDATE SET
    activitypub_likes_score = GREATEST(post_activitypub_like_tallies.activitypub_likes_score + v_delta, 0),
    activitypub_likes_count = GREATEST(post_activitypub_like_tallies.activitypub_likes_count + v_delta, 0);
  RETURN NEW;
END;
$function$

