fn_project_latest_change().definition:
CREATE OR REPLACE FUNCTION public.fn_project_latest_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  target_id UUID := (to_jsonb(NEW) ->> TG_ARGV[2])::uuid;
  change_filter TEXT := CASE WHEN TG_NARGS = 7 THEN format(' AND %I = %L', TG_ARGV[5], TG_ARGV[6]) ELSE '' END;
BEGIN
  -- Serialize on the target before re-reading the latest committed log entry.
  EXECUTE format('SELECT %I FROM %I.%I WHERE %I = $1 FOR UPDATE',
    TG_ARGV[1], TG_TABLE_SCHEMA, TG_ARGV[0], TG_ARGV[1]) USING target_id;
  EXECUTE format(
    'UPDATE %I.%I target SET %I = latest.value FROM
     (SELECT %I AS value FROM %I.%I WHERE %I = $1%s ORDER BY id DESC LIMIT 1) latest
     WHERE target.%I = $1 AND target.%I IS DISTINCT FROM latest.value',
    TG_TABLE_SCHEMA, TG_ARGV[0], TG_ARGV[3], TG_ARGV[4], TG_TABLE_SCHEMA,
    TG_TABLE_NAME, TG_ARGV[2], change_filter, TG_ARGV[1], TG_ARGV[3]) USING target_id;
  RETURN NEW;
END;
$function$

fn_project_mark_topic_alias_category_map.definition:
CREATE OR REPLACE FUNCTION public.fn_project_mark_topic_alias_category_mapping_dirty()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  dirty_alias_id UUID;
  dirty_alias TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.topic_id IS NULL THEN
      RETURN NEW;
    END IF;
    dirty_alias_id := NEW.id;
    dirty_alias := NEW.alias;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.topic_id IS NOT DISTINCT FROM OLD.topic_id THEN
      RETURN NEW;
    END IF;
    dirty_alias_id := NEW.id;
    dirty_alias := NEW.alias;
  ELSIF TG_OP = 'DELETE' THEN
    IF OLD.topic_id IS NULL THEN
      RETURN OLD;
    END IF;
    dirty_alias_id := OLD.id;
    dirty_alias := OLD.alias;
  END IF;

  INSERT INTO topic_alias_category_mapping_reconciliations (topic_alias_id, alias)
  VALUES (dirty_alias_id, dirty_alias)
  ON CONFLICT (topic_alias_id) DO UPDATE
  SET alias = EXCLUDED.alias,
      generation = topic_alias_category_mapping_reconciliations.generation + 1;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

fn_project_refresh_rss_feed_item_unmappe.definition:
CREATE OR REPLACE FUNCTION public.fn_project_refresh_rss_feed_item_unmapped_category_count()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  current_item_count BIGINT;
BEGIN
  IF TG_OP != 'INSERT' AND OLD.topic_id IS NULL THEN
    SELECT item_count INTO current_item_count
    FROM rss_feed_item_unmapped_category_counts
    WHERE category_text = LOWER(OLD.category_text)
    FOR UPDATE;

    IF current_item_count = 1 THEN
      DELETE FROM rss_feed_item_unmapped_category_counts
      WHERE category_text = LOWER(OLD.category_text);
    ELSIF current_item_count > 1 THEN
      UPDATE rss_feed_item_unmapped_category_counts
      SET item_count = item_count - 1
      WHERE category_text = LOWER(OLD.category_text);
    END IF;
  END IF;

  IF TG_OP != 'DELETE' AND NEW.topic_id IS NULL THEN
    INSERT INTO rss_feed_item_unmapped_category_counts (category_text, item_count)
    VALUES (LOWER(NEW.category_text), 1)
    ON CONFLICT (category_text) DO UPDATE
    SET item_count = rss_feed_item_unmapped_category_counts.item_count + 1;
  END IF;

  RETURN NULL;
END;
$function$

