fn_project_topic_aliases().definition:
CREATE OR REPLACE FUNCTION public.fn_project_topic_aliases()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  affected_topic_ids UUID[];
  affected_topic_id UUID;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT ARRAY_AGG(DISTINCT topic_id) INTO affected_topic_ids FROM new_aliases;
  ELSIF TG_OP = 'DELETE' THEN
    SELECT ARRAY_AGG(DISTINCT topic_id) INTO affected_topic_ids FROM old_aliases;
  ELSE
    SELECT ARRAY_AGG(DISTINCT topic_id) INTO affected_topic_ids FROM (
      SELECT topic_id FROM new_aliases UNION SELECT topic_id FROM old_aliases
    ) affected;
  END IF;
  -- Serialize cache projection by parent in a stable order before reading current aliases.
  FOR affected_topic_id IN
    SELECT id FROM topics WHERE id = ANY(affected_topic_ids) ORDER BY id FOR NO KEY UPDATE
  LOOP
    UPDATE topics SET aliases = COALESCE((
      SELECT ARRAY_AGG(alias ORDER BY alias) FROM topic_aliases
      WHERE topic_id = affected_topic_id
    ), '{}'::TEXT[]) WHERE id = affected_topic_id;
  END LOOP;
  RETURN NULL;
END;
$function$

fn_project_topic_image_placements().definition:
CREATE OR REPLACE FUNCTION public.fn_project_topic_image_placements()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND (
    (NEW.deleted_at IS NOT NULL AND OLD.deleted_at IS NULL)
    OR (NEW.merged_into_topic_id IS NOT NULL AND OLD.merged_into_topic_id IS NULL)
  ) THEN
    PERFORM fn_sync_image_surface_placement('topic-logo-image', NULL, NULL, NEW.id, NULL, NULL);
    PERFORM fn_sync_image_surface_placement('topic-hero-image', NULL, NULL, NEW.id, NULL, NULL);
    RETURN NEW;
  END IF;
  IF TG_OP = 'INSERT' OR NEW.logo_image_id IS DISTINCT FROM OLD.logo_image_id THEN
    PERFORM fn_sync_image_surface_placement('topic-logo-image', NEW.logo_image_id, NULL, NEW.id, NULL, NULL);
  END IF;
  IF TG_OP = 'INSERT' OR NEW.hero_image_id IS DISTINCT FROM OLD.hero_image_id THEN
    PERFORM fn_sync_image_surface_placement('topic-hero-image', NEW.hero_image_id, NULL, NEW.id, NULL, NULL);
  END IF;
  RETURN NEW;
END;
$function$

