fn_register_retained_image_identity().definition:
CREATE OR REPLACE FUNCTION public.fn_register_retained_image_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE pinned_uploader_id UUID;
BEGIN
  -- Cleanup may remove an unreferenced root between insertion and pinning.
  LOOP
    INSERT INTO retained_image_identities (id, created_by_id)
    VALUES (NEW.id, NEW.created_by_id)
    ON CONFLICT (id) DO NOTHING;
    SELECT created_by_id INTO pinned_uploader_id
    FROM retained_image_identities WHERE id = NEW.id FOR KEY SHARE;
    EXIT WHEN pinned_uploader_id IS NOT NULL;
  END LOOP;
  IF pinned_uploader_id <> NEW.created_by_id THEN
    RAISE EXCEPTION 'retained image uploader does not match the live image'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_admin_import_row_target().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_admin_import_row_target()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  batch_import_type import_entity_types;
BEGIN
  SELECT import_type
  INTO STRICT batch_import_type
  FROM admin_import_batches
  WHERE id = NEW.batch_id;

  IF NOT (
    (batch_import_type = 'topic' AND NEW.topic_id IS NOT NULL)
    OR (batch_import_type = 'rss_feed' AND NEW.rss_feed_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'admin import row target does not match batch import type %', batch_import_type
      USING ERRCODE = 'check_violation';
  END IF;

  RETURN NEW;
END;
$function$

