fn_reject_classifier_activation_lifecycl.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_classifier_activation_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.activated_at IS NOT DISTINCT FROM OLD.activated_at
    AND NEW.deactivated_at IS NOT DISTINCT FROM OLD.deactivated_at THEN
    RETURN NEW;
  END IF;
  IF OLD.activated_at IS NULL
    AND OLD.deactivated_at IS NULL
    AND NEW.activated_at IS NOT NULL
    AND NEW.deactivated_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF OLD.activated_at IS NOT NULL
    AND OLD.deactivated_at IS NULL
    AND NEW.activated_at IS NOT DISTINCT FROM OLD.activated_at
    AND NEW.deactivated_at IS NOT NULL THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '% activation lifecycle is immutable after each transition', TG_TABLE_NAME USING ERRCODE = '23514';
END $function$

fn_reject_classifier_batch_candidate_con.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_classifier_batch_candidate_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  batch classifier_decision_batches%ROWTYPE;
  candidate classifier_candidates%ROWTYPE;
  prompt classifier_prompt_versions%ROWTYPE;
  threshold classifier_candidate_thresholds%ROWTYPE;
  effective_lower NUMERIC(5,4);
  effective_upper NUMERIC(5,4);
BEGIN
  SELECT * INTO batch FROM classifier_decision_batches
  WHERE id = NEW.batch_id FOR SHARE;
  SELECT * INTO candidate FROM classifier_candidates
  WHERE id = NEW.candidate_id FOR SHARE;
  IF candidate.community_id IS NOT NULL
    AND (
      batch.scope_category <> 'community_ai'
      OR batch.scope_community_id IS DISTINCT FROM candidate.community_id
    ) THEN
    RAISE EXCEPTION 'community classifier candidate scope must match its batch' USING ERRCODE = '23514';
  END IF;
  SELECT * INTO prompt FROM classifier_prompt_versions
  WHERE id = NEW.prompt_version_id FOR SHARE;
  SELECT * INTO threshold FROM classifier_candidate_thresholds
  WHERE id = NEW.threshold_id FOR SHARE;
  IF threshold.id IS NULL
    OR threshold.classifier_id IS DISTINCT FROM NEW.classifier_id
    OR threshold.candidate_id IS DISTINCT FROM NEW.candidate_id
    OR threshold.prompt_version_id IS DISTINCT FROM NEW.prompt_version_id
    OR threshold.deactivated_at IS NOT NULL THEN
    RAISE EXCEPTION 'classifier batch candidate threshold must be its active configuration revision' USING ERRCODE = '23514';
  END IF;
  effective_lower := COALESCE(threshold.lower_threshold_override, prompt.default_lower_threshold);
  effective_upper := COALESCE(threshold.upper_threshold_override, prompt.default_upper_threshold);
  IF NEW.effective_lower_threshold IS DISTINCT FROM effective_lower
    OR NEW.effective_upper_threshold IS DISTINCT FROM effective_upper THEN
    RAISE EXCEPTION 'classifier batch candidate thresholds must match captured configuration' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

fn_reject_classifier_candidate_effective.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_classifier_candidate_effective_thresholds()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  defaults classifier_prompt_versions%ROWTYPE;
  effective_lower NUMERIC(5,4);
  effective_upper NUMERIC(5,4);
BEGIN
  SELECT * INTO defaults FROM classifier_prompt_versions
  WHERE id = NEW.prompt_version_id FOR SHARE;
  effective_lower := COALESCE(NEW.lower_threshold_override, defaults.default_lower_threshold);
  effective_upper := COALESCE(NEW.upper_threshold_override, defaults.default_upper_threshold);
  IF effective_lower < 0 OR effective_upper > 1 OR effective_lower >= effective_upper THEN
    RAISE EXCEPTION 'classifier candidate effective thresholds must be ordered probabilities' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

fn_reject_classifier_result_batch_scope(.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_classifier_result_batch_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  batch classifier_decision_batches%ROWTYPE;
  candidate classifier_candidates%ROWTYPE;
  prompt classifier_prompt_versions%ROWTYPE;
  batch_candidate classifier_decision_batch_candidates%ROWTYPE;
  effective_lower NUMERIC(5,4);
  effective_upper NUMERIC(5,4);
BEGIN
  SELECT * INTO batch FROM classifier_decision_batches WHERE id = NEW.batch_id FOR SHARE;
  SELECT * INTO candidate FROM classifier_candidates WHERE id = NEW.candidate_id FOR SHARE;
  SELECT * INTO prompt FROM classifier_prompt_versions
  WHERE id = NEW.prompt_version_id FOR SHARE;
  IF NEW.candidate_id IS NOT NULL THEN
    SELECT * INTO batch_candidate FROM classifier_decision_batch_candidates
    WHERE batch_id = NEW.batch_id AND candidate_id = NEW.candidate_id
    FOR SHARE;
  END IF;
  IF NEW.scope_category IS DISTINCT FROM batch.scope_category
    OR NEW.scope_community_id IS DISTINCT FROM batch.scope_community_id THEN
    RAISE EXCEPTION 'classifier result scope must match its batch' USING ERRCODE = '23514';
  END IF;
  IF candidate.community_id IS NOT NULL
    AND (
      batch.scope_category <> 'community_ai'
      OR batch.scope_community_id IS DISTINCT FROM candidate.community_id
    ) THEN
    RAISE EXCEPTION 'community classifier candidate scope must match its owning community' USING ERRCODE = '23514';
  END IF;
  IF NEW.candidate_id IS NOT NULL AND batch_candidate.batch_id IS NULL THEN
    RETURN NEW;
  END IF;
  effective_lower := COALESCE(
    batch_candidate.effective_lower_threshold,
    prompt.default_lower_threshold
  );
  effective_upper := COALESCE(
    batch_candidate.effective_upper_threshold,
    prompt.default_upper_threshold
  );
  IF NEW.effective_lower_threshold IS DISTINCT FROM effective_lower
    OR NEW.effective_upper_threshold IS DISTINCT FROM effective_upper THEN
    RAISE EXCEPTION 'classifier result thresholds must match prompt and candidate configuration' USING ERRCODE = '23514';
  END IF;
  IF NEW.threshold_id IS DISTINCT FROM batch_candidate.threshold_id THEN
    RAISE EXCEPTION 'classifier result threshold revision must match its batch candidate snapshot' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

fn_reject_community_prompt_result_config.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_community_prompt_result_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  batch classifier_decision_batches%ROWTYPE;
  prompt classifier_prompt_versions%ROWTYPE;
BEGIN
  SELECT * INTO batch FROM classifier_decision_batches WHERE id = NEW.batch_id FOR SHARE;
  SELECT * INTO prompt FROM classifier_prompt_versions
  WHERE id = NEW.prompt_version_id FOR SHARE;
  IF batch.post_id IS NULL THEN
    RAISE EXCEPTION 'community prompt classifier results require a post batch' USING ERRCODE = '23514';
  END IF;
  IF NEW.effective_lower_threshold IS DISTINCT FROM prompt.default_lower_threshold
    OR NEW.effective_upper_threshold IS DISTINCT FROM prompt.default_upper_threshold THEN
    RAISE EXCEPTION 'community prompt classifier result thresholds must match the prompt revision defaults' USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $function$

fn_reject_copyright_action_intent().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_action_intent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright action intents are durable saga records' USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(OLD.copyright_restriction_id, OLD.copyright_notice_deadline_id,
      OLD.expected_placement_revision, OLD.action)
    IS DISTINCT FROM ROW(NEW.copyright_restriction_id, NEW.copyright_notice_deadline_id,
      NEW.expected_placement_revision, NEW.action) THEN
    RAISE EXCEPTION 'copyright action intent identity and revision fence are immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.state IN ('completed', 'stale') AND NEW.state IS DISTINCT FROM OLD.state THEN
    RAISE EXCEPTION 'terminal copyright action intent cannot change' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.state IN ('blocked', 'failed') AND NEW.state IS DISTINCT FROM OLD.state
    AND NOT (NEW.state = 'pending' AND NEW.completed_at IS NULL
      AND NEW.completed_at_reason IS NULL AND NEW.claimed_at IS NULL
      AND NEW.delivery_attempt_count = 0) THEN
    RAISE EXCEPTION 'blocked and failed copyright actions may only be explicitly replayed' USING ERRCODE = 'check_violation';
  END IF;
  IF (NEW.delivery_attempt_count < OLD.delivery_attempt_count
      AND NOT (OLD.state IN ('blocked', 'failed') AND NEW.state = 'pending'
        AND NEW.delivery_attempt_count = 0))
    OR NEW.delivery_attempt_count > OLD.delivery_attempt_count + 1 THEN
    RAISE EXCEPTION 'copyright action intent attempts must advance one at a time' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.completed_at IS NOT NULL AND OLD.completed_at IS DISTINCT FROM NEW.completed_at
    AND NOT (OLD.state IN ('blocked', 'failed') AND NEW.state = 'pending' AND NEW.completed_at IS NULL) THEN
    RAISE EXCEPTION 'copyright action intent completion is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_assessment_source().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_assessment_source()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM copyright_notice_submissions submission
    WHERE submission.id = NEW.copyright_notice_submission_id
      AND submission.source_kind IN ('guest_form', 'email')
  ) AND NEW.assessed_by_id IS NULL THEN
    RAISE EXCEPTION 'guest and email copyright assessments require a human assessor' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_automated_assessment.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_automated_assessment_screening()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.assessed_by_id IS NOT NULL
    AND NEW.assessed_by_id IS NULL AND NEW.copyright_notice_form_screening_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.assessed_by_id IS NULL AND NOT fn_current_copyright_form_screening(
    NEW.copyright_notice_submission_id, NEW.copyright_notice_form_screening_id
  ) THEN
    RAISE EXCEPTION 'automated copyright assessment requires its current completed screen and complete structured US DMCA notice'
      USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.assessed_by_id IS NOT NULL AND NEW.copyright_notice_form_screening_id IS NOT NULL THEN
    RAISE EXCEPTION 'human copyright assessment cannot claim an automated form screening'
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_correspondence().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_correspondence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('app.copyright_retention_erasure', true) = 'on' THEN
    IF fn_copyright_retention_erasure_permitted(TG_TABLE_NAME, to_jsonb(OLD), to_jsonb(NEW)) THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright correspondence is a retained legal record' USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(
    OLD.copyright_notice_id,
    OLD.copyright_notice_submission_id,
    OLD.direction,
    OLD.composition_kind,
    OLD.correspondence_kind,
    NULL
  ) IS DISTINCT FROM ROW(
    NEW.copyright_notice_id,
    NEW.copyright_notice_submission_id,
    NEW.direction,
    NEW.composition_kind,
    NEW.correspondence_kind,
    NULL
  ) THEN
    RAISE EXCEPTION 'copyright correspondence identity is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.direction = 'inbound' AND OLD.body_ciphertext IS DISTINCT FROM NEW.body_ciphertext THEN
    RAISE EXCEPTION 'inbound copyright correspondence body is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_at IS NOT NULL AND ROW(
    OLD.body_ciphertext,
    OLD.approved_at
  ) IS DISTINCT FROM ROW(
    NEW.body_ciphertext,
    NEW.approved_at
  ) THEN
    RAISE EXCEPTION 'approved copyright correspondence is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.sent_at IS NOT NULL AND OLD.body_ciphertext IS DISTINCT FROM NEW.body_ciphertext THEN
    RAISE EXCEPTION 'sent copyright correspondence body is immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_at IS NULL AND NEW.approved_at IS NOT NULL AND NEW.approved_by_id IS NULL THEN
    RAISE EXCEPTION 'copyright correspondence approval requires an identified actor' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.drafted_by_id IS DISTINCT FROM NEW.drafted_by_id AND NEW.drafted_by_id IS NOT NULL THEN
    RAISE EXCEPTION 'copyright correspondence drafter cannot be reassigned' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.approved_by_id IS DISTINCT FROM NEW.approved_by_id
    AND OLD.approved_by_id IS NOT NULL
    AND NEW.approved_by_id IS NOT NULL THEN
    RAISE EXCEPTION 'copyright correspondence approver cannot be reassigned' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.sent_at IS NOT NULL AND OLD.sent_at IS DISTINCT FROM NEW.sent_at THEN
    RAISE EXCEPTION 'copyright correspondence delivery is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_deadline().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright deadlines are durable statutory records' USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(
    OLD.copyright_notice_id,
    OLD.qualifying_counter_notice_assessment_id,
    OLD.earliest_restoration_at,
    OLD.escalation_at,
    OLD.restoration_deadline_at
  ) IS DISTINCT FROM ROW(
    NEW.copyright_notice_id,
    NEW.qualifying_counter_notice_assessment_id,
    NEW.earliest_restoration_at,
    NEW.escalation_at,
    NEW.restoration_deadline_at
  ) THEN
    RAISE EXCEPTION 'copyright deadline origin and schedule are immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF (OLD.resolved_at IS NOT NULL OR OLD.cancelled_at IS NOT NULL)
    AND ROW(OLD.resolved_at, OLD.cancelled_at) IS DISTINCT FROM ROW(NEW.resolved_at, NEW.cancelled_at) THEN
    RAISE EXCEPTION 'copyright deadline terminal outcome is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_delivery_intent_tran.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_delivery_intent_transition()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('app.copyright_retention_erasure', true) = 'on' THEN
    IF fn_copyright_retention_erasure_permitted(TG_TABLE_NAME, to_jsonb(OLD), to_jsonb(NEW)) THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright delivery intents are retained' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.copyright_notice_id IS DISTINCT FROM OLD.copyright_notice_id
    OR NEW.copyright_notice_email_intake_id IS DISTINCT FROM OLD.copyright_notice_email_intake_id
    OR NEW.copyright_notice_submission_id IS DISTINCT FROM OLD.copyright_notice_submission_id
    OR NEW.copyright_notice_correspondence_message_id IS DISTINCT FROM OLD.copyright_notice_correspondence_message_id
    OR NEW.recipient_role IS DISTINCT FROM OLD.recipient_role
    OR NEW.delivery_kind IS DISTINCT FROM OLD.delivery_kind
    OR NEW.channel IS DISTINCT FROM OLD.channel
    OR NEW.body_ciphertext IS DISTINCT FROM OLD.body_ciphertext
    OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key THEN
    RAISE EXCEPTION 'copyright delivery intent facts are immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.recipient_user_id IS DISTINCT FROM NEW.recipient_user_id THEN
    IF OLD.recipient_user_id IS NULL OR NEW.recipient_user_id IS NOT NULL THEN
      RAISE EXCEPTION 'copyright delivery recipient cannot change' USING ERRCODE = 'check_violation';
    END IF;
    NEW.recipient_user_erased_at := CURRENT_TIMESTAMP;
  ELSIF NEW.recipient_user_erased_at IS DISTINCT FROM OLD.recipient_user_erased_at THEN
    RAISE EXCEPTION 'copyright delivery recipient erasure is system-managed' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.state = 'bounced' AND NEW.state IS DISTINCT FROM OLD.state THEN
    RAISE EXCEPTION 'terminal copyright delivery intent cannot change' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.state = 'failed' AND NEW.state IS DISTINCT FROM OLD.state
    AND NOT (
      NEW.state = 'pending' AND NEW.claimed_at IS NULL AND NEW.failed_at IS NULL
      AND NEW.next_attempt_at IS NULL AND NEW.delivery_attempt_count = 0
    ) THEN
    RAISE EXCEPTION 'failed copyright delivery intents may only be explicitly replayed'
      USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.state = 'sent' AND NEW.state NOT IN ('sent', 'bounced') THEN
    RAISE EXCEPTION 'terminal copyright delivery intent cannot change' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_human_actor().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_human_actor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF to_jsonb(NEW) ->> TG_ARGV[0] IS NULL THEN
    RAISE EXCEPTION 'copyright human decisions require an identified actor' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_immutable_with_actor.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_immutable_with_actor_erasure()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  actor_column text;
  old_actor jsonb;
  new_actor jsonb;
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('app.copyright_retention_erasure', true) = 'on' THEN
    IF fn_copyright_retention_erasure_permitted(TG_TABLE_NAME, to_jsonb(OLD), to_jsonb(NEW)) THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright legal records are retained' USING ERRCODE = 'check_violation';
  END IF;
  IF (to_jsonb(OLD) - TG_ARGV) IS DISTINCT FROM (to_jsonb(NEW) - TG_ARGV) THEN
    RAISE EXCEPTION 'copyright legal records are immutable' USING ERRCODE = 'check_violation';
  END IF;
  FOREACH actor_column IN ARRAY TG_ARGV LOOP
    old_actor := to_jsonb(OLD) -> actor_column;
    new_actor := to_jsonb(NEW) -> actor_column;
    IF old_actor IS DISTINCT FROM new_actor
      AND (old_actor = 'null'::jsonb OR new_actor <> 'null'::jsonb) THEN
      RAISE EXCEPTION 'copyright legal record actors may only be erased' USING ERRCODE = 'check_violation';
    END IF;
  END LOOP;
  RETURN NEW;
END;
$function$

fn_reject_copyright_lifecycle_event_sour.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_lifecycle_event_source_notice()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN

  -- A NULL notice pairs only with an email-intake reply, which is the one intent with no notice.
  IF NEW.copyright_notice_delivery_intent_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM copyright_notice_delivery_intents source
    WHERE source.id = NEW.copyright_notice_delivery_intent_id
      AND source.copyright_notice_id IS NOT DISTINCT FROM NEW.copyright_notice_id
  ) THEN RAISE EXCEPTION 'lifecycle delivery intent belongs to another notice' USING ERRCODE = 'check_violation'; END IF;

  IF NEW.media_delivery_registry_key IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM media_delivery_registry_records source
    JOIN copyright_notice_targets target ON target.placement_id = source.placement_id
    WHERE source.delivery_key = NEW.media_delivery_registry_key
      AND target.copyright_notice_id = NEW.copyright_notice_id
  ) THEN RAISE EXCEPTION 'lifecycle media delivery record belongs to another notice' USING ERRCODE = 'check_violation'; END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_notice_identity().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_notice_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('app.copyright_retention_erasure', true) = 'on' THEN
    IF fn_copyright_retention_erasure_permitted(TG_TABLE_NAME, to_jsonb(OLD), to_jsonb(NEW)) THEN RETURN NEW; END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright notices are retained legal records' USING ERRCODE = 'check_violation';
  END IF;
  IF ROW(
    OLD.jurisdiction,
    OLD.legal_basis,
    OLD.received_at,
    OLD.claimant_display_name,
    OLD.claimant_contact_ciphertext,
    OLD.work_description,
    OLD.policy_version
  ) IS DISTINCT FROM ROW(
    NEW.jurisdiction,
    NEW.legal_basis,
    NEW.received_at,
    NEW.claimant_display_name,
    NEW.claimant_contact_ciphertext,
    NEW.work_description,
    NEW.policy_version
  ) THEN
    RAISE EXCEPTION 'copyright notice identity and receipt snapshot are immutable' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.claimant_user_id IS DISTINCT FROM NEW.claimant_user_id AND NEW.claimant_user_id IS NOT NULL THEN
    RAISE EXCEPTION 'copyright notice claimant account cannot be reassigned' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_notice_immutable_evi.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_notice_immutable_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND current_setting('app.copyright_retention_erasure', true) = 'on' THEN
    IF fn_copyright_retention_erasure_permitted(TG_TABLE_NAME, to_jsonb(OLD), to_jsonb(NEW)) THEN RETURN NEW; END IF;
  END IF;
  RAISE EXCEPTION 'copyright legal receipt and evidence records are immutable' USING ERRCODE = 'check_violation';
END;
$function$

fn_reject_copyright_notice_lifecycle().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_notice_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'copyright restrictions are append-only legal blockers' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.accepted_at IS NOT NULL AND OLD.accepted_at IS DISTINCT FROM NEW.accepted_at THEN
    RAISE EXCEPTION 'copyright notice acceptance is irreversible' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.provisional_withholding_at IS NOT NULL
    AND OLD.provisional_withholding_at IS DISTINCT FROM NEW.provisional_withholding_at THEN
    RAISE EXCEPTION 'copyright notice provisional withholding timestamp is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_copyright_repeat_infringer_inc.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_copyright_repeat_infringer_incident()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
