fn_reject_media_placement().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_media_placement()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'media placements are retained for legal revision fencing' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'media placement revision must advance by exactly one' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.retired_at IS NOT DISTINCT FROM OLD.retired_at
    AND NEW.retirement_reason IS NOT DISTINCT FROM OLD.retirement_reason
    AND NEW.copyright_withheld_at IS NOT DISTINCT FROM OLD.copyright_withheld_at THEN
    RAISE EXCEPTION 'media placement lifecycle update must change availability' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.retired_at IS NOT NULL AND NEW.retired_at IS NULL THEN
    NEW.activation_revision := NEW.revision;
  ELSIF NEW.activation_revision IS DISTINCT FROM OLD.activation_revision THEN
    RAISE EXCEPTION 'media placement activation revision is system-managed' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$function$

fn_reject_membership_administrator_refun.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_membership_administrator_refund_request_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE valid_context BOOLEAN;
BEGIN
  SELECT operation.operation_kind = 'administrator_refund' AND operation.remaining_refundable_minor_units = NEW.amount_minor_units AND operation.currency_code = NEW.currency_code INTO valid_context FROM membership_operations operation WHERE operation.id = NEW.membership_operation_id;
  IF valid_context IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'administrator refund request does not match its operation context' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END $function$

fn_reject_membership_grant_activation_pe.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_membership_grant_activation_period_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'membership grant activation periods cannot be deleted';
  END IF;

  IF OLD.ended_at IS NULL
    AND NEW.ended_at IS NOT NULL
    AND ROW(
      NEW.id, NEW.membership_grant_id, NEW.user_id, NEW.started_at
    ) IS NOT DISTINCT FROM ROW(
      OLD.id, OLD.membership_grant_id, OLD.user_id, OLD.started_at
    )
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'membership grant activation periods only allow an open-to-ended lifecycle transition';
END $function$

fn_reject_membership_refund_metadata_sca.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_membership_refund_metadata_scan_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE lease_matches BOOLEAN;
BEGIN
  SELECT operation.execution_claim_token = NEW.lease_token INTO lease_matches FROM membership_refund_operation_attempts attempt INNER JOIN membership_operations operation ON operation.id = attempt.membership_operation_id WHERE attempt.id = NEW.membership_refund_operation_attempt_id;
  IF lease_matches IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'membership refund metadata scan lease is stale'; END IF;
  IF TG_OP = 'UPDATE' AND (OLD.completed_at IS NOT NULL OR NEW.created_at IS DISTINCT FROM OLD.created_at OR NEW.membership_refund_operation_attempt_id IS DISTINCT FROM OLD.membership_refund_operation_attempt_id OR (NEW.completed_at IS NOT NULL AND NEW.next_provider_refund_id IS NOT NULL)) THEN RAISE EXCEPTION 'membership refund metadata scan cannot be reopened or rewritten after completion'; END IF;
  RETURN NEW;
END $function$

fn_reject_membership_refund_operation_at.definition:
CREATE OR REPLACE FUNCTION public.fn_reject_membership_refund_operation_attempt_context()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE valid_context BOOLEAN;
BEGIN
  SELECT operation.operation_kind IN ('automatic_refund', 'ineligible_purchase_reversal', 'collision_resolution', 'administrator_refund') AND operation.provider = NEW.provider AND operation.environment = NEW.environment AND operation.application_id = NEW.application_id AND operation.currency_code = NEW.currency_code AND NEW.amount_minor_units <= operation.remaining_refundable_minor_units INTO valid_context FROM membership_operations operation WHERE operation.id = NEW.membership_operation_id;
  IF valid_context IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'refund attempt does not match its operation context' USING ERRCODE = '23514'; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.fn_reject_membership_refund_operation_attempt_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'membership refund operation attempts cannot be deleted'; END IF;
  IF OLD.provider_refund_id IS NULL AND NEW.provider_refund_id IS NOT NULL AND ROW(NEW.id, NEW.membership_operation_id, NEW.attempt_ordinal, NEW.provider, NEW.environment, NEW.application_id, NEW.provider_idempotency_key, NEW.amount_minor_units, NEW.currency_code, NEW.created_at) IS NOT DISTINCT FROM ROW(OLD.id, OLD.membership_operation_id, OLD.attempt_ordinal, OLD.provider, OLD.environment, OLD.application_id, OLD.provider_idempotency_key, OLD.amount_minor_units, OLD.currency_code, OLD.created_at) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'membership refund operation attempts only allow provider refund ID enrichment';
END $function$

fn_reject_moderation_appeal_resolution().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_moderation_appeal_resolution()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.resolved_at IS NULL AND OLD.resolution_action IS NULL
    AND NEW.resolved_at IS NOT NULL AND NEW.resolution_action IS NOT NULL THEN
    RETURN NEW;
  END IF;
  IF OLD.resolved_at IS DISTINCT FROM NEW.resolved_at
    OR OLD.resolution_action IS DISTINCT FROM NEW.resolution_action THEN
    RAISE EXCEPTION 'moderation appeal resolution is immutable once set';
  END IF;
  RETURN NEW;
END $function$

fn_reject_mutation().definition:
CREATE OR REPLACE FUNCTION public.fn_reject_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  actor_column TEXT;
  actor_columns TEXT[] := COALESCE(TG_ARGV, ARRAY[]::TEXT[]);
  old_row JSONB;
  new_row JSONB;
BEGIN
  IF TG_OP = 'DELETE' AND pg_trigger_depth() > 1 THEN RETURN OLD; END IF;
  IF TG_OP = 'UPDATE' THEN
    old_row := to_jsonb(OLD);
    new_row := to_jsonb(NEW);
    IF (old_row - actor_columns) IS NOT DISTINCT FROM (new_row - actor_columns) THEN
      FOREACH actor_column IN ARRAY actor_columns LOOP
        IF new_row -> actor_column IS DISTINCT FROM old_row -> actor_column
          AND new_row -> actor_column IS DISTINCT FROM 'null'::jsonb THEN
          RAISE EXCEPTION '% rows are append-only', TG_TABLE_NAME USING ERRCODE = 'check_violation';
        END IF;
      END LOOP;
      RETURN NEW;
    END IF;
  END IF;
  RAISE EXCEPTION '% rows are append-only', TG_TABLE_NAME USING ERRCODE = 'check_violation';
END;
$function$

