fn_text_to_timestamptz(text_value text).definition:
CREATE OR REPLACE FUNCTION public.fn_text_to_timestamptz(text_value text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  normalized TEXT;
BEGIN
  normalized := TRIM(BOTH E'\t\n\r\f ' FROM text_value);
  IF normalized IS NULL OR normalized = '' OR LOWER(normalized) = 'null' THEN
    RETURN NULL;
  END IF;

  -- Strip a known RFC 822 weekday prefix ("Mon, " … "Sun, ").
  -- Anchored to standard abbreviations; non-standard tokens fall through to the exception handler.
  normalized := regexp_replace(normalized, '^(Mon|Tue|Wed|Thu|Fri|Sat|Sun),\s*', '', 'i');
  -- Collapse a named-zone prefix glued to a numeric offset: "GMT-0700" -> "-0700",
  -- "UTC+05:30" -> "+05:30". PostgreSQL rejects the glued form but accepts the bare offset.
  normalized := regexp_replace(normalized, '(?:GMT|UTC)\s*([+-]\d{1,2}:?\d{2})', '\1', 'i');

  IF normalized ~ '[Zz]$' OR
     normalized ~ '[\+\-]\d{1,2}:?\d{2}$' OR
     normalized ~ ' [A-Z]{3,}$' THEN
    RETURN normalized::timestamptz;
  END IF;
  RETURN timezone('UTC', normalized::timestamp);
EXCEPTION
  -- Best-effort parser over untrusted feed input: any value PostgreSQL still can't parse
  -- degrades to NULL so the generated column falls back to uuid_extract_timestamp(id),
  -- rather than aborting the INSERT and the whole fetchRssFeed job. Three distinct SQLSTATE
  -- codes (22023, 22007, 22009) have already appeared from real feeds; a narrow catch would leak.
  WHEN OTHERS THEN
    RAISE WARNING 'fn_text_to_timestamptz: unparseable date "%" (SQLSTATE: %)', text_value, SQLSTATE;
    RETURN NULL;
END;
$function$

fn_update_agent_moderation_transparency(.definition:
CREATE OR REPLACE FUNCTION public.fn_update_agent_moderation_transparency()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE v_community_id uuid; v_post_community_id uuid; v_current_community_id uuid; v_agent_deleted_at timestamptz; v_prompt_deleted_at timestamptz; v_cap_deleted_at timestamptz;
BEGIN
  -- Lock the FK parents before taking the projection locks. A concurrent hard
  -- delete already owns the parent row before its row trigger can take an
  -- advisory lock; reversing this order would form a parent-row/advisory-lock
  -- cycle with this INSERT.
  PERFORM 1 FROM agents WHERE id = NEW.agent_id FOR KEY SHARE;
  PERFORM 1 FROM agent_prompts WHERE id = NEW.prompt_id FOR KEY SHARE;
  -- Do not lock the post here: community deletion owns the community before
  -- cascading to posts, so a post-to-community lock would invert that order.
  -- Snapshot and revalidate instead; an unstable post scope is withheld.
  SELECT community_id INTO v_post_community_id FROM posts WHERE id = NEW.post_id;
  SELECT community_id, deleted_at INTO v_community_id, v_cap_deleted_at
  FROM community_agent_prompts WHERE id = NEW.prompt_id;
  IF v_community_id IS NOT NULL THEN
    PERFORM 1 FROM communities WHERE id = v_community_id FOR KEY SHARE;
    IF NOT FOUND THEN
      v_community_id := NULL;
      v_cap_deleted_at := NULL;
    END IF;
  END IF;
  SELECT community_id, deleted_at INTO v_current_community_id, v_cap_deleted_at
  FROM community_agent_prompts WHERE id = NEW.prompt_id FOR SHARE;
  IF v_current_community_id IS NULL THEN
    v_community_id := NULL;
    v_cap_deleted_at := NULL;
  ELSIF v_current_community_id IS DISTINCT FROM v_community_id THEN
    RAISE EXCEPTION 'community prompt changed during moderation projection' USING ERRCODE = '40001';
  END IF;
  IF (SELECT community_id FROM posts WHERE id = NEW.post_id)
      IS DISTINCT FROM v_post_community_id THEN
    NEW.moderation_transparency_category := NULL;
    NEW.moderation_transparency_community_id := NULL;
    RETURN NEW;
  END IF;
  -- Every caller then takes agent before prompt, which prevents an event from
  -- observing a cap assignment half-way through its lifecycle transaction.
  PERFORM fn_lock_moderation_transparency_projection('agent', NEW.agent_id);
  PERFORM fn_lock_moderation_transparency_projection('prompt', NEW.prompt_id);
  SELECT agent.deleted_at, prompt.deleted_at
    INTO v_agent_deleted_at, v_prompt_deleted_at
  FROM agents agent JOIN agent_prompts prompt ON prompt.id = NEW.prompt_id
  WHERE agent.id = NEW.agent_id;
  v_agent_deleted_at := date_trunc('milliseconds', v_agent_deleted_at);
  v_prompt_deleted_at := date_trunc('milliseconds', v_prompt_deleted_at);
  v_cap_deleted_at := date_trunc('milliseconds', v_cap_deleted_at);
  NEW.moderation_transparency_category := NULL;
  NEW.moderation_transparency_community_id := NULL;
  IF NEW.deleted_at IS NOT NULL
    OR (v_agent_deleted_at IS NOT NULL AND uuid_extract_timestamp(NEW.id) >= v_agent_deleted_at)
    OR (v_prompt_deleted_at IS NOT NULL AND uuid_extract_timestamp(NEW.id) >= v_prompt_deleted_at)
    OR (v_cap_deleted_at IS NOT NULL AND uuid_extract_timestamp(NEW.id) >= v_cap_deleted_at) THEN
    RETURN NEW;
  END IF;
  -- A community prompt remains a community-AI event. A platform agent keeps
  -- its platform category, but its post scope must still exclude it from the
  -- global projection because raw community analytics can identify the event.
  NEW.moderation_transparency_category := CASE WHEN v_community_id IS NULL THEN 'agent_moderation' ELSE 'community_ai' END;
  NEW.moderation_transparency_community_id := COALESCE(v_community_id, v_post_community_id);
  RETURN NEW;
END $function$

fn_update_classifier_run_scope().definition:
CREATE OR REPLACE FUNCTION public.fn_update_classifier_run_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.post_id IS NULL THEN
    NEW.community_identity_id := NULL;
  ELSE
    SELECT community_id INTO NEW.community_identity_id FROM posts
    WHERE id = NEW.post_id FOR KEY SHARE;
  END IF;
  RETURN NEW;
END $function$

fn_update_media_delivery_change_authorit.definition:
CREATE OR REPLACE FUNCTION public.fn_update_media_delivery_change_authority()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE current_generation bigint; current_desired_state media_delivery_desired_states;
BEGIN
  SELECT generation, desired_state INTO current_generation, current_desired_state FROM media_delivery_registry_records
    WHERE delivery_key = NEW.delivery_key FOR NO KEY UPDATE;
  IF current_generation IS DISTINCT FROM NEW.generation THEN RETURN NULL; END IF;
  NEW.desired_state := current_desired_state;
  RETURN NEW;
END;
$function$

fn_update_media_delivery_registry_genera.definition:
CREATE OR REPLACE FUNCTION public.fn_update_media_delivery_registry_generation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT'
    OR NEW.desired_state IS DISTINCT FROM OLD.desired_state
    OR NEW.generation IS DISTINCT FROM OLD.generation THEN
    NEW.generation := nextval('media_delivery_registry_generation_sequence');
  ELSE
    NEW.generation := OLD.generation;
  END IF;
  RETURN NEW;
END;
$function$

fn_update_moderation_report_transparency.definition:
CREATE OR REPLACE FUNCTION public.fn_update_moderation_report_transparency_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.moderation_transparency_community_id IS NULL THEN
    SELECT community_id INTO NEW.moderation_transparency_community_id FROM posts WHERE id = NEW.post_id;
  END IF;
  RETURN NEW;
END $function$

fn_update_notification_publication_targe.definition:
CREATE OR REPLACE FUNCTION public.fn_update_notification_publication_target()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.publication_post_id := COALESCE(NEW.publication_post_id, NEW.post_id);
    NEW.publication_rss_feed_item_id := COALESCE(
      NEW.publication_rss_feed_item_id,
      NEW.rss_feed_item_id
    );
  ELSE
    NEW.publication_post_id := COALESCE(
      NEW.publication_post_id,
      NEW.post_id,
      OLD.publication_post_id,
      OLD.post_id
    );
    NEW.publication_rss_feed_item_id := COALESCE(
      NEW.publication_rss_feed_item_id,
      NEW.rss_feed_item_id,
      OLD.publication_rss_feed_item_id,
      OLD.rss_feed_item_id
    );
  END IF;
  RETURN NEW;
END;
$function$

fn_update_parent_notice_scope().definition:
CREATE OR REPLACE FUNCTION public.fn_update_parent_notice_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE notice_id UUID;
BEGIN
  IF NEW.copyright_notice_id IS NULL THEN
    EXECUTE format('SELECT copyright_notice_id FROM %I.%I WHERE id = $1',
      TG_TABLE_SCHEMA, TG_ARGV[0]) INTO notice_id
      USING (to_jsonb(NEW) ->> TG_ARGV[1])::uuid;
    IF notice_id IS NULL AND to_jsonb(NEW) ->> TG_ARGV[1] IS NOT NULL THEN
      RAISE EXCEPTION '% parent % does not exist', TG_TABLE_NAME, TG_ARGV[0]
        USING ERRCODE = 'foreign_key_violation';
    END IF;
    NEW.copyright_notice_id := notice_id;
  END IF;
  RETURN NEW;
END;
$function$

fn_update_updated_at().definition:
CREATE OR REPLACE FUNCTION public.fn_update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$function$

fn_user_deletion_has_remaining_owned_dat.definition:
CREATE OR REPLACE FUNCTION public.fn_user_deletion_has_remaining_owned_data(target_user_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
DECLARE
  ownership RECORD;
  has_rows BOOLEAN;
BEGIN
  FOR ownership IN
    SELECT * FROM (VALUES
      ('posts', 'created_by_id'),
      ('post_topic_alias_sources', 'contributor_user_id'),
      ('user_email_addresses', 'user_id'),
      ('user_phone_numbers', 'user_id'),
      ('user_passkeys', 'user_id'),
      ('user_totp_authenticators', 'user_id'),
      ('api_keys', 'user_id'),
      ('user_sessions', 'user_id'),
      ('facebook_accounts', 'user_id'),
      ('apple_accounts', 'user_id'),
      ('google_accounts', 'user_id'),
      ('x_accounts', 'user_id'),
      ('linkedin_accounts', 'user_id'),
      ('microsoft_accounts', 'user_id'),
      ('github_accounts', 'user_id'),
      ('bluesky_link_completions', 'user_id'),
      ('bluesky_linked_accounts', 'user_id'),
      ('session_referral_attributions', 'user_id')
    ) AS configured(table_name, column_name)
  LOOP
    EXECUTE format(
      'SELECT EXISTS (SELECT 1 FROM %I WHERE %I = $1)',
      ownership.table_name,
      ownership.column_name
    ) INTO has_rows USING target_user_id;
    IF has_rows THEN RETURN TRUE; END IF;
  END LOOP;

  FOR ownership IN
    SELECT DISTINCT table_name, 'user_id' AS column_name
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND column_name = 'user_id'
      AND table_name LIKE '%\_votes' ESCAPE '\'
  LOOP
    EXECUTE format(
      'SELECT EXISTS (SELECT 1 FROM %I WHERE user_id = $1)',
      ownership.table_name
    ) INTO has_rows USING target_user_id;
    IF has_rows THEN RETURN TRUE; END IF;
  END LOOP;

  FOR ownership IN
    SELECT DISTINCT table_name, 'subject_id' AS column_name
    FROM information_schema.columns
    WHERE table_schema = 'public'
      AND column_name = 'subject_id'
      AND table_name LIKE 'relation\_\_user\_\_%' ESCAPE '\'
      AND table_name NOT LIKE '%\_votes' ESCAPE '\'
  LOOP
    EXECUTE format(
      'SELECT EXISTS (SELECT 1 FROM %I WHERE subject_id = $1)',
      ownership.table_name
    ) INTO has_rows USING target_user_id;
    IF has_rows THEN RETURN TRUE; END IF;
  END LOOP;

  IF EXISTS (
    SELECT 1 FROM user_lists WHERE owner_user_id = target_user_id AND removed_at IS NULL
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM bluesky_link_authorizations
    WHERE user_id = target_user_id
      AND status IN ('pending', 'callback_claimed', 'handoff_ready', 'attached')
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM bluesky_follow_records
    WHERE follower_user_id = target_user_id OR followee_user_id = target_user_id
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM user_data_requests
    WHERE user_id = target_user_id
      AND (
        (completed_at IS NULL AND failed_at IS NULL)
        OR (completed_at IS NOT NULL AND failed_at IS NULL AND s3_key IS NOT NULL)
      )
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM oauth_clients
    WHERE owner_user_id = target_user_id AND revoked_at IS NULL
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM oauth_grants
    WHERE user_id = target_user_id AND revoked_at IS NULL
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM oauth_refresh_token_families family
    JOIN oauth_grants oauth_grant ON oauth_grant.id = family.grant_id
    WHERE oauth_grant.user_id = target_user_id AND family.revoked_at IS NULL
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM oauth_access_tokens access
    JOIN oauth_grants oauth_grant ON oauth_grant.id = access.grant_id
    WHERE oauth_grant.user_id = target_user_id AND access.revoked_at IS NULL
  ) THEN RETURN TRUE; END IF;
  IF EXISTS (
    SELECT 1 FROM oauth_refresh_tokens refresh
    JOIN oauth_refresh_token_families family ON family.id = refresh.family_id
    JOIN oauth_grants oauth_grant ON oauth_grant.id = family.grant_id
    WHERE oauth_grant.user_id = target_user_id AND refresh.revoked_at IS NULL
  ) THEN RETURN TRUE; END IF;
  RETURN FALSE;
END;
$function$
